# Wi-Fi vs 802.15.4 Spectral Coexistence Analyzer
class SpectralCoexistenceAnalyzer:
    WIFI_CHANNELS_20MHZ = {
        1: (2401.0, 2423.0, 2412.0),
        6: (2426.0, 2448.0, 2437.0),
        11: (2451.0, 2473.0, 2462.0)
    }

    @classmethod
    def evaluate_802154_channel(cls, channel_154: int) -> dict:
        f_center = 2405.0 + 5.0 * (channel_154 - 11)
        # 802.15.4 occupies roughly +/- 1.0 MHz around center
        f_min = f_center - 1.0
        f_max = f_center + 1.0

        conflicts = []
        for wifi_ch, (w_min, w_max, w_center) in cls.WIFI_CHANNELS_20MHZ.items():
            # Check for spectral overlap
            if not (f_max < w_min or f_min > w_max):
                distance_to_center = abs(f_center - w_center)
                conflicts.append({
                    "wifi_ch": wifi_ch,
                    "distance_mhz": distance_to_center
                })

        is_safe = len(conflicts) == 0
        recommendation = "RECOMMENDED (INTERFERENCE-FREE)" if is_safe else "AVOID (HEAVY WI-FI CONFLICT)"
        if channel_154 in (15, 20):
            recommendation = "MODERATE (GUARD-BAND GAP, MINOR SIDELOBES)"
        if channel_154 == 26:
            recommendation = "BEST PRACTICE (TOTAL OUT-OF-BAND ISOLATION)"

        return {
            "channel": channel_154,
            "center_freq_mhz": f_center,
            "is_clear": is_safe,
            "conflicts": conflicts,
            "recommendation": recommendation
        }

analyzer = SpectralCoexistenceAnalyzer()
print("=== IEEE 802.15.4 vs 2.4 GHz Wi-Fi Spectral Coexistence ===")
for ch in [11, 15, 17, 20, 24, 25, 26]:
    report = analyzer.evaluate_802154_channel(ch)
    print(f"802.15.4 Ch {ch:02d} ({report['center_freq_mhz']:.1f} MHz): {report['recommendation']}")
    for c in report['conflicts']:
        print(f"   -> Overlaps with Wi-Fi Channel {c['wifi_ch']} (Delta: {c['distance_mhz']:.1f} MHz)")

# 802.15.4 Device Capability & Topology Validation Engine
class DeviceRoleEngine:
    ROLES = {"PAN_COORDINATOR": 0, "ROUTER_FFD": 1, "END_DEVICE_FFD": 2, "LEAF_RFD": 3}

    def __init__(self, device_id: str, is_ffd: bool, role: str):
        self.device_id = device_id
        self.is_ffd = is_ffd
        if not is_ffd and role in ("PAN_COORDINATOR", "ROUTER_FFD"):
            raise ValueError(f"Reduced Function Device (RFD) cannot assume role {role}!")
        self.role = role
        self.associated_children = []
        self.parent = None

    def can_route_traffic(self) -> bool:
        return self.is_ffd and self.role in ("PAN_COORDINATOR", "ROUTER_FFD")

    def associate_child(self, child_device: 'DeviceRoleEngine'):
        if not self.can_route_traffic():
            raise PermissionError(f"Device {self.device_id} ({self.role}) cannot accept child associations!")
        self.associated_children.append(child_device.device_id)
        child_device.parent = self.device_id

# Simulate Topology Creation
pan_coord = DeviceRoleEngine("COORD_001", is_ffd=True, role="PAN_COORDINATOR")
router_ffd = DeviceRoleEngine("ROUTER_002", is_ffd=True, role="ROUTER_FFD")
temp_sensor_rfd = DeviceRoleEngine("TEMP_SENS_003", is_ffd=False, role="LEAF_RFD")
motion_sensor_rfd = DeviceRoleEngine("MOT_SENS_004", is_ffd=False, role="LEAF_RFD")

# Form Cluster-Tree Links
pan_coord.associate_child(router_ffd)
router_ffd.associate_child(temp_sensor_rfd)
pan_coord.associate_child(motion_sensor_rfd)

print("=== IEEE 802.15.4 Network Role & Association Topology ===")
for node in [pan_coord, router_ffd, temp_sensor_rfd, motion_sensor_rfd]:
    print(f"Node [{node.device_id}]: FFD={str(node.is_ffd):5s} | Role={node.role:15s} | Parent={str(node.parent):10s} | Children={node.associated_children}")

# IEEE 802.15.4 Unit Backoff Period & Timing Architecture
class IEEE802154BackoffTiming:
    SYMBOL_DURATION_US = 16.0           # 1 symbol = 16 us at 2.4 GHz (62.5 ksymbols/s)
    SYMBOLS_PER_BACKOFF_PERIOD = 20     # aUnitBackoffPeriod = 20 symbols

    @classmethod
    def get_unit_backoff_period_us(cls) -> float:
        return cls.SYMBOLS_PER_BACKOFF_PERIOD * cls.SYMBOL_DURATION_US

    @classmethod
    def calculate_backoff_delay_us(cls, backoff_units: int) -> float:
        return backoff_units * cls.get_unit_backoff_period_us()

timing = IEEE802154BackoffTiming()
unit_us = timing.get_unit_backoff_period_us()

print("=== IEEE 802.15.4 CSMA/CA Backoff Timing Architecture ===")
print(f"Symbol Duration: {timing.SYMBOL_DURATION_US:.1f} us")
print(f"Symbols per Unit Backoff: {timing.SYMBOLS_PER_BACKOFF_PERIOD} symbols")
print(f"aUnitBackoffPeriod: {unit_us:.1f} us ({unit_us / 1000.0:.3f} ms)")

for units in [1, 3, 7, 15, 31]:
    delay_us = timing.calculate_backoff_delay_us(units)
    print(f"Backoff {units:2d} periods = {delay_us:7.1f} us ({delay_us/1000.0:6.3f} ms)")

# IEEE 802.15.4 PAN Formation & Multi-Channel Scanner Engine
class PanFormationScanner:
    CHANNELS = list(range(11, 27))   # Channels 11 to 26

    def __init__(self, simulated_spectrum_noise: dict, existing_networks: dict):
        self.noise_map = simulated_spectrum_noise   # channel -> noise_power_dbm
        self.networks = existing_networks           # channel -> list of PAN_IDs

    def perform_energy_detection_scan(self) -> dict:
        # Step through all 16 channels and record peak RF power
        energy_results = {}
        for ch in self.CHANNELS:
            power = self.noise_map.get(ch, -98.0)
            energy_results[ch] = power
        return energy_results

    def perform_active_scan(self, candidate_channels: list[int]) -> dict:
        # Broadcast Beacon Request on quiet candidate channels and listen for PAN beacons
        discovered_pans = {}
        for ch in candidate_channels:
            active_pans = self.networks.get(ch, [])
            discovered_pans[ch] = active_pans
        return discovered_pans

    def form_new_pan(self, preferred_pan_id: int = 0xABCD) -> dict:
        # 1. Execute ED Scan
        ed_results = self.perform_energy_detection_scan()
        # Find quiet channels (noise < -85 dBm)
        quiet_channels = [ch for ch, pwr in ed_results.items() if pwr < -85.0]
        if not quiet_channels:
            raise RuntimeError("All channels exhibit severe RF interference!")

        # 2. Execute Active Scan on quiet channels
        active_results = self.perform_active_scan(quiet_channels)

        # 3. Select best channel (lowest noise) with no PAN ID conflict
        sorted_channels = sorted(quiet_channels, key=lambda c: ed_results[c])
        selected_channel = sorted_channels[0]
        occupied_pans_on_ch = active_results.get(selected_channel, [])

        assigned_pan_id = preferred_pan_id
        while assigned_pan_id in occupied_pans_on_ch or assigned_pan_id in (0x0000, 0xFFFF):
            assigned_pan_id = (assigned_pan_id + 1) & 0xFFFE

        return {
            "status": "PAN_ESTABLISHED",
            "selected_channel": selected_channel,
            "channel_noise_dbm": ed_results[selected_channel],
            "pan_id": f"0x{assigned_pan_id:04X}",
            "conflicting_pans_avoided": occupied_pans_on_ch
        }

# Simulate realistic enterprise RF environment: Wi-Fi on Ch 1, 6, 11
spectrum_noise = {
    11: -65.0, 12: -68.0, 13: -72.0, 14: -75.0,  # Wi-Fi Ch 1 overlap
    16: -62.0, 17: -64.0, 18: -69.0, 19: -71.0,  # Wi-Fi Ch 6 overlap
    21: -60.0, 22: -63.0, 23: -68.0, 24: -70.0,  # Wi-Fi Ch 11 overlap
    15: -90.0, 20: -92.0, 25: -91.0, 26: -96.0   # Clean guard gaps
}
existing_nets = {
    26: [0x1111, 0x2222]   # Existing building automation networks on Ch 26
}

scanner = PanFormationScanner(spectrum_noise, existing_nets)
pan_record = scanner.form_new_pan(preferred_pan_id=0x1111)

print("=== IEEE 802.15.4 Autonomous PAN Formation Record ===")
for k, v in pan_record.items():
    print(f"  {k:25s}: {v}")

# IEEE 802.15.4 Address Space Partitioning & Translation Table Engine
class IEEE802154AddressEngine:
    SPECIAL_ADDRESSES = {
        0x0000: "PAN_COORDINATOR",
        0xFFFE: "UNASSOCIATED_DEVICE",
        0xFFFF: "MAC_BROADCAST"
    }

    def __init__(self, pan_id: int):
        self.pan_id = pan_id
        # EUI-64 (str) -> Short Address (int)
        self.eui64_to_short = {}
        # Short Address (int) -> EUI-64 (str)
        self.short_to_eui64 = {}
        self.next_allocatable_short = 0x0001

    def allocate_short_address(self, eui64_hex: str) -> int:
        if eui64_hex in self.eui64_to_short:
            return self.eui64_to_short[eui64_hex]

        if self.next_allocatable_short > 0xFFFD:
            raise OverflowError("PAN short address space completely exhausted (65,533 nodes max)!")

        short_addr = self.next_allocatable_short
        self.next_allocatable_short += 1

        self.eui64_to_short[eui64_hex] = short_addr
        self.short_to_eui64[short_addr] = eui64_hex
        return short_addr

    def classify_address(self, addr: int) -> str:
        if addr in self.SPECIAL_ADDRESSES:
            return self.SPECIAL_ADDRESSES[addr]
        elif 0x0001 <= addr <= 0xFFFD:
            return "ASSOCIATED_UNICAST_NODE"
        else:
            return "INVALID_ADDRESS"

engine = IEEE802154AddressEngine(pan_id=0xABCD)

# Register factory devices with unique 64-bit EUI-64 MAC addresses
nodes = [
    "00:12:4B:00:14:D5:2F:01",
    "00:12:4B:00:14:D5:2F:02",
    "00:12:4B:00:14:D5:2F:03"
]

print("=== IEEE 802.15.4 Address Allocation & Resolution ===")
for eui in nodes:
    short = engine.allocate_short_address(eui)
    role = engine.classify_address(short)
    print(f"EUI-64 [{eui}] -> Assigned Short Address: 0x{short:04X} ({role})")

for special in [0x0000, 0xFFFE, 0xFFFF]:
    print(f"Special Address 0x{special:04X}: {engine.classify_address(special)}")
